from monai.utils import MetaKeys, SpaceKeys

__all__ = ["MetaTensor"]


class MetaTensor:
    def __init__(self, data, affine=None, meta=None):
        self.data = np.asarray(data)
        self.affine = np.asarray(affine if affine is not None else np.eye(self.data.ndim + 1), dtype=float)
        self.meta = dict(meta or {})
        self.meta.setdefault(MetaKeys.AFFINE, self.affine.copy())
        # MONAI tensors are in the RAS coordinate system by default; only
        # override this when the caller explicitly provides another space.
        self.meta.setdefault(MetaKeys.SPACE, SpaceKeys.RAS)

    def clone(self):
        return MetaTensor(self.data.copy(), affine=self.affine.copy(), meta=deepcopy(self.meta))

    @property
    def shape(self):
        return self.data.shape

    @property
    def ndim(self):
        return self.data.ndim

    @property
    def space(self):
        return self.meta.get(MetaKeys.SPACE, SpaceKeys.RAS)

