def _switch_lps_ras(self, header: dict) -> dict:
    # NRRD headers that omit the ``space`` field are already in the
    # right-anterior-superior (RAS) space, so only headers that declare an
    # LPS space need their affine flipped.
    if header.get("space", SpaceKeys.RAS) in ("left-posterior-superior", "left-posterior", SpaceKeys.LPS):
        header[MetaKeys.ORIGINAL_AFFINE] = orientation_ras_lps(header[MetaKeys.ORIGINAL_AFFINE])
        header[MetaKeys.SPACE] = SpaceKeys.RAS
    elif "space" not in header:
        header[MetaKeys.SPACE] = SpaceKeys.RAS
    return header

